import java.util.Scanner;

public class Main {
    public static void solve() {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int total = n * (n - 1) / 2;
        int limit = n * (n - 1);
        int[][] dp = new int[n + 1][limit + 1];
        int[][] dp1 = new int[n + 1][limit + 1];
        dp[1][total] = 1;
        for (int i = 2; i <= n; i++) {
            int start = total - (i - 1) * (i - 2) / 2;
            int end = total + (i - 1) * (i - 2) / 2;
            for (int x = start; x <= end; x++) {
                for (int delta = -i + 1; delta < i; delta++) {
                    int index = x + delta;
                    if (0 <= index && index <= limit) {
                        dp[i][index] = (dp[i][index] + (int)((long)dp[i - 1][x] * (i - Math.abs(delta))) % m) % m;
                    }
                }
            }
        }
        for (int i = 2; i <= n; i++) {
            int start = total - (i - 1) * (i - 2) / 2;
            int end = total + (i - 1) * (i - 2) / 2;
            for (int x = start; x <= end; x++) {
                dp1[i][x] = (int)((long)dp1[i - 1][x] * i % m);
            }
            for (int x = start; x <= end; x++) {
                for (int d = 1; d < i; d++) {
                    int idx = x - d;
                    if (0 <= idx && idx <= limit) {
                        dp1[i][idx] = (int)((long)dp1[i][idx] + (long)dp[i - 1][x] * (i - d) % m) % m;
                    }
                }
            }
        }
        int sum = 0;
        for (int i = total + 1; i <= limit; i++) {
            sum = (sum + dp1[n][i]) % m;
        }
        System.out.println(sum);
        sc.close();
    }

    public static void main(String[] args) {
        solve();
    }
}
